import{_ as o,o as l,c as i,ah as r}from"./chunks/framework.DjU4PSOm.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"이 문서에 대하여","slug":"이-문서에-대하여","link":"#이-문서에-대하여","children":[]},{"level":2,"title":"1주차 — 윤리학이란 무엇인가","slug":"_1주차-—-윤리학이란-무엇인가","link":"#_1주차-—-윤리학이란-무엇인가","children":[]},{"level":2,"title":"2주차 — 아리스토텔레스와 에우다이모니아","slug":"_2주차-—-아리스토텔레스와-에우다이모니아","link":"#_2주차-—-아리스토텔레스와-에우다이모니아","children":[]},{"level":2,"title":"3주차 — 습관화, 헥시스, 중용, 실천적 지혜","slug":"_3주차-—-습관화-헥시스-중용-실천적-지혜","link":"#_3주차-—-습관화-헥시스-중용-실천적-지혜","children":[]},{"level":2,"title":"4주차 — 칸트","slug":"_4주차-—-칸트","link":"#_4주차-—-칸트","children":[]},{"level":2,"title":"참고: 아직 강의로 다뤄지지 않은 것으로 보이는 슬라이드 내용 (4주차)","slug":"참고-아직-강의로-다뤄지지-않은-것으로-보이는-슬라이드-내용-4주차","link":"#참고-아직-강의로-다뤄지지-않은-것으로-보이는-슬라이드-내용-4주차","children":[]}],"relativePath":"philosophy/Ethics/08. 슬라이드에 없는 강의 추가 내용.md","filePath":"philosophy/Ethics/08. 슬라이드에 없는 강의 추가 내용.md"}'),n={name:"philosophy/Ethics/08. 슬라이드에 없는 강의 추가 내용.md"};function s(e,t,a,u,q,g){return l(),i("div",null,[...t[0]||(t[0]=[r('<h2 id="이-문서에-대하여" tabindex="-1">이 문서에 대하여 <a class="header-anchor" href="#이-문서에-대하여" aria-label="Permalink to &quot;이 문서에 대하여&quot;">​</a></h2><p>교수님이 Canvas에 올린 공식 슬라이드(PDF)와 실제 TransLive 강의 자막을 대조해서, <strong>슬라이드에는 없고 강의에서만 구두로 설명된 내용</strong>(구체적 예시, 문장 단위 정독, 학생과의 즉석 Q&amp;A, 슬라이드보다 상세한 논증 전개)만 골라 정리했습니다. 슬라이드에 이미 있는 핵심 개념·정의·구조는 반복하지 않았습니다. 완전한 문장 단위 대조는 아니며, <strong>슬라이드에 없는 실질적 내용 위주</strong>로 추렸습니다.</p><hr><h2 id="_1주차-—-윤리학이란-무엇인가" tabindex="-1">1주차 — 윤리학이란 무엇인가 <a class="header-anchor" href="#_1주차-—-윤리학이란-무엇인가" aria-label="Permalink to &quot;1주차 — 윤리학이란 무엇인가&quot;">​</a></h2><p>슬라이드는 오리엔테이션(언어 정책, 평가, 커리큘럼)과 Rachels 1장 요약(최소 개념, 딜레마 등)을 다루지만, 아래는 슬라이드에 없는 것들:</p><ul><li><strong>나이에 따른 위계 사례</strong>: 윤리(ethics) vs 도덕(morality) 구별을 설명하며 든, 나이가 다른 사람들을 다르게 대우하는 구체적 사례 — 슬라이드의 &quot;언어학 비유&quot;만 있고 이 사례는 없음.</li><li><strong>&quot;어떻게 살아야 하는가, </strong>그리고 왜<strong>&quot;</strong> — 소크라테스 정식을 인용할 때 &quot;그리고 왜(and why)&quot;라는 구절 자체가 왜 중요한지에 대한 정독 포인트. 슬라이드는 인용문만 보여주고 이 구문 분석은 생략.</li><li><strong>부정행위 친구 사례의 세 이론 비교</strong>: 친구의 시험 부정행위를 목격했을 때 — 덕윤리는 &quot;정직하고 용기 있는 사람이라면 어떻게 할까&quot;, 의무론은 &quot;이 행동을 용인하는 원칙이 보편화될 수 있는가&quot;, 공리주의는 &quot;어느 쪽이 더 큰 해를 줄이는가&quot;를 각각 묻는다는 비교. 슬라이드는 &quot;everyone cheats&quot; 오류만 언급하고 이 3이론 비교는 없음.</li><li><strong>&quot;만족한 짐승&quot; 비유</strong>: 성찰 없는 삶을 상징하는 표현 — 슬라이드의 소크라테스 인용문에는 없음.</li><li><strong>Rachels 텍스트의 &quot;handicapped children&quot; 표현에 대한 언어 민감성 논의</strong>: &quot;장애가 있는 아이들(children with disabilities)&quot;이라는 표현으로 바꿔 부르는 현대적 감수성 논의, AI 시대의 지역별 학력 격차 예시. 슬라이드 15는 원문 스캔 이미지만 보여주고 이 논의는 없음.</li></ul><h2 id="_2주차-—-아리스토텔레스와-에우다이모니아" tabindex="-1">2주차 — 아리스토텔레스와 에우다이모니아 <a class="header-anchor" href="#_2주차-—-아리스토텔레스와-에우다이모니아" aria-label="Permalink to &quot;2주차 — 아리스토텔레스와 에우다이모니아&quot;">​</a></h2><p>슬라이드는 텔레올로지·에우다이모니아·1권 7장 정독의 핵심 뼈대를 담고 있지만, 다음은 강의에서만 나온 세부사항:</p><ul><li><strong>스마트폰/소셜미디어 구체 사례</strong>: &quot;요즘 스마트폰 과사용 경험 있지 않나요?&quot;, 좋아요·댓글 반응에 따른 자기만족·불안 경험 등 학생들에게 직접 던진 질문들. 슬라이드는 &quot;소셜미디어가 가시성을 가치와 동일시하게 만든다&quot;는 한 문장 요약뿐.</li><li><strong>&quot;철학과 지원 증가&quot; 화두</strong>: AI 시대 생존 전략으로 철학을 선택하는지, 다른 동기인지 묻는 질의. 슬라이드에 없음.</li><li><strong>삶을 계속 미루는 문제의 구체적 예시</strong>: &quot;졸업 후에 인생이 시작된다&quot;, &quot;승진 후에&quot;, &quot;충분한 사회적 인정을 받은 후에&quot; 등 구체적 예문들. 슬라이드는 &quot;Life will begin after graduation. After promotion. After recognition.&quot;로 짧게만 언급.</li><li><strong>1권 7장 문장 단위 정독의 그리스어 문법 분석</strong>: 아가톤(agathon)·텔로스(telos)·텔레이온(teleion) 각 용어가 원문 문장에서 정확히 어느 구절에 대응하는지, &quot;그것을 위하여 모든 것이 행해지는 바로 그것&quot;이라는 구문이 왜 목적을 정의하는지에 대한 문장별 해설. 슬라이드는 최종 결론(개념 정의 카드)만 제공.</li><li><strong>일원론(monism)/이원론(dualism)/다원론(pluralism) 삼분</strong> 설명 — 슬라이드는 &quot;ethical monism has not yet been proved&quot;라고만 언급하고, monism/dualism/pluralism을 나란히 정의하는 강의 설명은 없음.</li><li><strong>친구관계·중병 가족 돌봄 충돌 사례</strong>: 경력과 중병 가족 돌봄이 충돌할 때 &quot;둘 다 가치 있다&quot;는 말만으로는 결정이 안 된다는 구체적 딜레마. 슬라이드 discussion question(19페이지 &quot;Plurality of Goods&quot;)은 있지만 이 구체적 사례는 없음.</li><li><strong>일제강점기 독립운동가 사례</strong>: &quot;행복을 정의를 위해 희생할 수 있는가&quot;라는 논의 질문에 실제 예시로 언급됨. 슬라이드는 추상적 질문만 있고 이 역사적 사례는 없음.</li><li><strong>경쟁 세일즈 인간관계/명예 불안정성에 대한 구체 설명 확장</strong> — 슬라이드보다 더 풍부한 예시로 진행됨(광고와 충동구매, 경쟁적 제도의 승리 vs 정의 등).</li></ul><h2 id="_3주차-—-습관화-헥시스-중용-실천적-지혜" tabindex="-1">3주차 — 습관화, 헥시스, 중용, 실천적 지혜 <a class="header-anchor" href="#_3주차-—-습관화-헥시스-중용-실천적-지혜" aria-label="Permalink to &quot;3주차 — 습관화, 헥시스, 중용, 실천적 지혜&quot;">​</a></h2><p>가장 많은 추가 내용이 있었던 주차. 슬라이드에 없는 것들:</p><ul><li><strong>언어 습득 비유의 구체적 질의</strong>: &quot;한국어를 몇 살에 배우기 시작했나요?&quot;라는 실제 질문과, 언어 습득 과정(교사·가족·친구와의 일상적 연습)을 윤리적 능력 발달과 나란히 놓는 상세 설명. 슬라이드에는 이 비유 자체가 없음(슬라이드는 돌 비유만 사용).</li><li><strong>싱가포르 쓰레기 무단투기 처벌 사례</strong>: 법의 교육적 기능을 설명하며 든 구체적 국가 사례. 슬라이드는 이 사례가 없고 일반적 서술(&quot;tax law, education law...&quot;)만 있음.</li><li><strong>대학 부정행위 환경 사례</strong>: 대학이 공식적으로 부정행위를 금지하면서 동시에 경쟁적 환경을 조성해 부정행위를 조장하는 모순 사례. 슬라이드에 없음.</li><li><strong>한국 정치 체제가 무엇을 함양하는지 묻는 질의</strong>: &quot;경쟁? 불안감? 패배에 대한 두려움?&quot;라는 학생 대상 실제 질문. 슬라이드는 일반론만 서술.</li><li><strong>연구자의 정직/부정직 습관화 사례, 학대적 리더십 사례</strong>: 반복된 행동이 행위자 자신을 변화시킨다는 논점의 구체적 현대 예시(연구 부정행위, 리더십 학대). 슬라이드는 건축가/음악가 비유만 사용.</li><li><strong>&quot;당신의 습관은 무엇인가?&quot; 직접 질문</strong>: 일상 루틴과 도덕적 습관의 차이를 설명하며 학생들에게 던진 질문. 슬라이드에 없음.</li><li><strong>넛징(nudging) 자판기 예시</strong>: 과자 자판기 배치가 식습관을 형성하는 구체적 사례. 슬라이드는 &quot;default setting&quot; 정도만 언급.</li><li><strong>소크라테스적 주지주의 비판의 구체적 사례들</strong>: 과음이 해로운 걸 알면서도 못 끊는 경우, 거짓말이 잘못인 걸 알면서도 명예 위협시 거짓말하는 경우 — akrasia(의지의 나약함) 설명에 쓰인 구체적 예시. 슬라이드는 &quot;akrasia&quot;라는 용어만 소개.</li><li><strong>자선단체 기부 동기의 다중성</strong>: 관심/전략/마케팅 이점이 동시에 작용하는 기업 기부 사례 — 이건 사실 4주차 슬라이드에 있음(주의: 이 항목은 4주차 자막에서 언급되었으나 위치상 3주차 논의와 혼동 주의).</li><li><strong>온라인 분노 사례</strong>: 잘못된 대상에게 향하거나 사실 확인 전에 일어나거나 가시성을 추구하는 온라인 분노의 병리 — 슬라이드는 &quot;Appropriate anger&quot; 항목에 간단히만 언급, 온라인 특유의 병리적 패턴 설명은 강의에서만.</li><li><strong>AI 학생 이탈 예측 시스템의 구체적 질문 목록</strong>: &quot;학생에게 연락해야 하는가? 개인정보는? 낙인효과는? 데이터가 불평등을 재생산하는가? 누가 책임지는가?&quot; — 슬라이드도 유사 질문을 담고 있으나(19페이지), 강의는 더 풍부한 질문 목록을 제시.</li><li><strong>기후변화 지식과 행동의 괴리, 사회제도의 편견(암묵적 편견) 논의</strong>: 명시적으로 평등을 지지하면서 무의식적으로 특정 집단과 능력을 연관짓는 사례 등 — 슬라이드보다 상세.</li></ul><h2 id="_4주차-—-칸트" tabindex="-1">4주차 — 칸트 <a class="header-anchor" href="#_4주차-—-칸트" aria-label="Permalink to &quot;4주차 — 칸트&quot;">​</a></h2><p>슬라이드가 매우 상세해서(35페이지) 겹치는 부분이 많지만, 강의에서만 나온 것:</p><ul><li><strong>자살/우울증 관련 신중한 주의사항</strong>: &quot;생명 보존&quot; 예시를 설명하며 &quot;이것은 자살, 정신질환, 견딜 수 없는 고통에 대한 완전한 논의가 아니며, 심각한 우울증을 겪는 사람을 의료·사회적 맥락 없이 판단하는 데 사용되어서는 안 된다&quot;는 교수님의 명시적 주의. 슬라이드는 이 예시를 간단히만 언급(18페이지)하고 이 윤리적 주의사항은 없음.</li><li><strong>쇼펜하우어 인용</strong>: 인간이 자신의 가장 깊은 동기를 완전히 확신할 수 없다는 논점에 쇼펜하우어를 명시적으로 인용. 슬라이드에 이 인용은 없음.</li><li><strong>아담 스미스의 &quot;공정한 관찰자&quot;와의 비교</strong>: 칸트의 &quot;합리적이고 공정한 관찰자&quot; 사고실험이 애덤 스미스의 이론과 정확히 같지는 않다는 명시적 구별. 슬라이드에 없음.</li><li><strong>부패한 관리·부정직 기업의 구체적 사고실험</strong>: &quot;부패한 관리가 부유하고 권력 있고 건강하고 존경받는다면&quot;, &quot;소비자를 속이고 노동자를 착취해 이익을 낸 기업&quot; — 슬라이드는 추상적 개념만 제시하고 이 구체적 사례는 강의에서 추가.</li><li><strong>자동차 운전 사례(moral luck)</strong>: 이 비유 자체는 슬라이드 28페이지에 있으나(두 careful/careless drivers), 강의 자막에는 해당 부분이 아직 도달하지 않음 — 참고로 이 세션의 자막은 &quot;worthiness to be happy&quot; 결론부에서 끝났으므로 슬라이드 후반부(자율성, AI 응용, 넛징/내부고발, 기후/공급망, 실천 프레임워크, 핵심 요약)는 <strong>아직 강의로 다뤄지지 않았을 가능성이 높음</strong> — 다음 시간 확인 필요.</li></ul><hr><h2 id="참고-아직-강의로-다뤄지지-않은-것으로-보이는-슬라이드-내용-4주차" tabindex="-1">참고: 아직 강의로 다뤄지지 않은 것으로 보이는 슬라이드 내용 (4주차) <a class="header-anchor" href="#참고-아직-강의로-다뤄지지-않은-것으로-보이는-슬라이드-내용-4주차" aria-label="Permalink to &quot;참고: 아직 강의로 다뤄지지 않은 것으로 보이는 슬라이드 내용 (4주차)&quot;">​</a></h2><p>4주차 자막은 &quot;행복할 자격(worthiness to be happy)&quot; 결론까지만 진행되었습니다. 슬라이드에는 있지만 지금까지 받은 자막에는 등장하지 않은 이후 내용:</p><ul><li>자율성(autonomy)과 타율성(heteronomy) — 슬라이드 29</li><li>AI·전문직·학문적 진실성 응용 — 슬라이드 30</li><li>알고리즘 채용·딥페이크·프라이버시 — 슬라이드 31</li><li>넛징·내부고발·돌봄윤리 비교 — 슬라이드 32</li><li>기후·공급망·분산 책임 — 슬라이드 33</li><li>칸트적 분석 실천 프레임워크(5단계) — 슬라이드 34</li><li>핵심 요약 및 최종 토론 — 슬라이드 35</li></ul><p>이 부분은 다음 수업 자막을 받으면 이어서 정리하겠습니다.</p>',20)])])}const d=o(n,[["render",s]]);export{_ as __pageData,d as default};
